  const addrs = [["config", F.CONFIG], ["program", L.PROGRAM], ["arena", arena], ["roster", roster], ["receipt", L.receiptPda(sid)], ["claims", L.claimsPda(sid)], ["pool", pool], ["pool token account", c.ata(pool)], ["token program", L.TOKEN], ...field.flatMap((e, i) => [[`entry ${i} registry`, L.regPda(e.id)], [`entry ${i} sealed strategy`, L.stratPda(e.id)], [`entry ${i} owner wallet`, c.players[e.owner].publicKey], [`entry ${i} token account`, c.ata(c.players[e.owner].publicKey)]])];
  const statuses = (await sleepRpc(c.URL, "getSignatureStatuses", [enterSigs, { searchTransactionHistory: true }])).result.value; const slots = [...new Set(statuses.map(s => s?.slot).filter(Boolean))];
  const history = {};
  for (const [who, u] of viewers) { const self = who.startsWith("an entrant") ? 1 : null; const mineIdx = field.map((e, i) => e.owner === self ? i : -1).filter(i => i >= 0);
    const lists = {}; for (const [name, a] of addrs) { const r = await sleepRpc(u, "getSignaturesForAddress", [a.toBase58(), { limit: 40 }]); const hits = (r.result ?? []).map(x => enterSigs.indexOf(x.signature)).filter(i => i >= 0 && !mineIdx.includes(i)); if (hits.length) lists[name] = hits; }
    const txSeen = {}; const txLeak = new Set(); let visibleBodies = 0, redacted = 0, absent = 0;
    for (let i = 0; i < enterSigs.length; i++) { if (mineIdx.includes(i)) continue; for (const enc of ["json", "jsonParsed", "base64"]) { const r = await sleepRpc(u, "getTransaction", [enterSigs[i], { maxSupportedTransactionVersion: 0, encoding: enc }]); if (!r.result) { absent++; continue; } const m = r.result.transaction?.message; const raw = Array.isArray(r.result.transaction) ? Buffer.from(r.result.transaction[0], "base64") : null; const hasBody = m ? (m.accountKeys?.length ?? 0) > 0 || (m.instructions?.length ?? 0) > 0 : raw ? raw.length > 140 : false; hasBody ? visibleBodies++ : redacted++; found(r.result, self).forEach(x => txLeak.add(x)); if (!txSeen[enc]) txSeen[enc] = { keys: Object.keys(r.result), meta: r.result.meta ? Object.entries(r.result.meta).filter(([, v]) => v !== null && !(Array.isArray(v) && v.length === 0)).map(([k]) => k) : [] }; } }
    let blockHas = 0, blockTxs = 0; const blockLeak = new Set(); let blockNote = "";
    for (const slot of slots) { const r = await sleepRpc(u, "getBlock", [slot, { maxSupportedTransactionVersion: 0, transactionDetails: "full", rewards: false, encoding: "json" }]); if (!r.result) { blockNote = "getBlock: " + String(r.error?.message ?? "no block").slice(0, 90); continue; } for (const t of r.result.transactions ?? []) { const s = t.transaction?.signatures?.[0]; const i = enterSigs.indexOf(s); if (i >= 0 && !mineIdx.includes(i)) { blockHas++; found(t, self).forEach(x => blockLeak.add(x)); } blockTxs++; } }
    history[who] = { lists, txLeak: [...txLeak], blockLeak: [...blockLeak] };
    log(`   ${who}${self !== null ? " (its own entry excluded)" : ""}:`);
    log(`      signature lists that include an Enter: ${Object.keys(lists).length ? Object.entries(lists).map(([k, v]) => `${k} -> entry ${v.join("/")}`).join("; ") : "none"}`);
    log(`      getTransaction (3 encodings per Enter): ${visibleBodies} with a body, ${redacted} redacted, ${absent} not returned | field identifiers in them: ${short([...txLeak])}${Object.keys(txSeen).length ? " | fields returned: " + JSON.stringify(txSeen.json?.keys ?? []) + " non-empty meta: " + JSON.stringify(txSeen.json?.meta ?? []) : ""}`);
    log(`      getBlock on the ${slots.length} slots of the Enters: ${blockHas} Enter transactions present among ${blockTxs} | identifiers in them: ${short([...blockLeak])} ${blockNote}`);
    // THE LEAK TEST: can this viewer tie an entry to this season? Directly (a body or block that names it) or by correlation (a signature list of something that names the season and one that names the strategy share a signature)
    const seasonSide = new Set(["arena", "roster", "receipt", "claims", "pool", "pool token account"]); const seasonSigs = new Set(Object.entries(lists).filter(([k]) => seasonSide.has(k)).flatMap(([, v]) => v)); const entrySide = new Map(); for (const [k, v] of Object.entries(lists)) if (k.startsWith("entry ")) for (const i of v) (entrySide.get(i) ?? entrySide.set(i, new Set()).get(i)).add(k);
    const joined = [...entrySide.keys()].filter(i => seasonSigs.has(i));
    history[who].joined = joined; check(`${who}: no transaction body or block names another entry`, txLeak.size === 0 && blockLeak.size === 0, `bodies: ${short([...txLeak])}; blocks: ${short([...blockLeak])}`);
    check(`${who}: signature lists do not tie an entry to this season`, joined.length === 0, joined.length ? `entries ${joined.join(",")} appear both in a list that names the season and in a list that names the entry` : `season-side lists with an Enter: ${seasonSigs.size}; entry-side: ${entrySide.size}`); }
  // 4. what an anonymous live feed delivered while the entries went in
